package com.dy.artisan3d.data.modelimport kotlinx.serialization.Serializable@Serializabledata class ProductDto(    val id: Int,    val slug: String,    val translations: Map<String, ProductTranslationDto> = emptyMap(), // Til kodi (uz, ru, en, tr, va h.k.) kalit sifatida    val images: ImageDto,    val category: CategoryDto // Avvalgi darsda yozganimiz)@Serializabledata class ProductTranslationDto(    val name: String,    val description: String)@Serializabledata class ImageDto(    val main: String,    val glb: String?,    val extra: List<String>)